import hashlib, math
s = ""
ref = math.factorial(375)//math.factorial(250)
print("LEN", len(s))
print("MATCH_FACT_RATIO", s == str(ref))
print("SHA256_RECOMPUTED", hashlib.sha256(s.encode()).hexdigest())
print("TRAILING_ZEROS", len(s)-len(s.rstrip("0")))
print("DIGITS_REF", len(str(ref)))
print("MOD", ref % 1000003)
